import sys
from fractions import Fraction as Q
sys.path.insert(0, sys.argv[1])
from spiral_ln.evaluation_gold_calibration import LabelTable, CELLS3, dawid_skene_moments, dawid_skene_three_raters


def compositions(total, parts):
    if parts == 1:
        yield (total,)
        return
    for k in range(total + 1):
        for rest in compositions(total - k, parts - 1):
            yield (k,) + rest


found = []
for comp in compositions(10, 8):
    if min(comp) == 0:
        continue
    table = LabelTable(dict(zip(CELLS3, comp)))
    mom = dawid_skene_moments(table)
    if all(c != 0 for c in mom["covariances"].values()) and mom["radicand"] < 0:
        found.append((comp, mom["radicand"], mom["covariances"]))
print(len(found))
for f in found[:5]:
    print(f)
# also: positive radicand but out of range
out = []
for comp in compositions(10, 8):
    if min(comp) == 0:
        continue
    table = LabelTable(dict(zip(CELLS3, comp)))
    fit = dawid_skene_three_raters(table, "rater_1_informative")
    if fit["status"] in ("exact", "bracketed") and not fit["in_range"]:
        out.append((comp, fit["status"]))
print("out of range", len(out), out[:3])

